:root {
  --bg: #1e1e2e;
  --card-bg: #2a2a3c;
  --text: #e0e0f0;
  --text-muted: #a0a0b8;
  --accent: #89b4fa;
  --accent-hover: #a6c8ff;
  --accent-pressed: #6a9ae0;
  --border: #3e3e52;
  --radius: 12px;
  --shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background: var(--bg);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: radial-gradient(circle at 30% 20%, #2e2e44, var(--bg));
}

.card {
  width: 100%;
  max-width: 720px;
  background: var(--card-bg);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 32px 28px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

header {
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 4px;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
}

.swatches {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
}

.swatch {
  flex: 1 1 0;
  min-width: 100px;
  max-width: 140px;
  display: flex;
  flex-direction: column;
  border-radius: var(--radius);
  overflow: hidden;
  background: #1a1a28;
  border: 2px solid transparent;
  transition: border-color 0.2s, transform 0.15s;
}

.swatch.locked {
  border-color: var(--accent);
}

.color-area {
  height: 120px;
  display: flex;
  align-items: flex-end;
  padding: 8px;
  position: relative;
}

.hex {
  font-family: 'SF Mono', 'Cascadia Code', 'Fira Code', monospace;
  font-size: 0.9rem;
  font-weight: 600;
  background: rgba(0, 0, 0, 0.55);
  color: #fff;
  padding: 2px 8px;
  border-radius: 6px;
  letter-spacing: 0.04em;
  backdrop-filter: blur(4px);
}

.lock-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 10px 8px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  font-size: 0.85rem;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.15s, color 0.15s;
}

.lock-btn:hover {
  background: rgba(255, 255, 255, 0.06);
  color: var(--text);
}

.lock-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.lock-btn:active {
  background: rgba(255, 255, 255, 0.1);
}

.lock-btn[aria-pressed="true"] {
  color: var(--accent);
}

.lock-icon {
  font-size: 1rem;
  line-height: 1;
}

.btn-generate {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  padding: 16px 24px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: inherit;
  color: #1e1e2e;
  background: var(--accent);
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn-generate:hover {
  background: var(--accent-hover);
}

.btn-generate:focus-visible {
  outline: 3px solid #fff;
  outline-offset: 2px;
}

.btn-generate:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

.btn-icon {
  font-size: 1.2rem;
  display: inline-block;
}

footer {
  text-align: center;
  color: var(--text-muted);
  font-size: 0.9rem;
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .swatches {
    gap: 8px;
  }
  .swatch {
    min-width: 80px;
  }
  .color-area {
    height: 90px;
  }
  .hex {
    font-size: 0.8rem;
    padding: 1px 6px;
  }
  .lock-btn {
    font-size: 0.8rem;
    padding: 8px 4px;
  }
}

@media (max-width: 360px) {
  .swatches {
    flex-direction: column;
    align-items: stretch;
  }
  .swatch {
    max-width: none;
    flex-direction: row;
  }
  .color-area {
    flex: 1;
    height: 60px;
  }
  .lock-btn {
    padding: 8px 12px;
  }
}

(function () {
  'use strict';

  const swatchesContainer = document.getElementById('swatches');
  const generateBtn = document.getElementById('generate');

  const NUM_SWATCHES = 5;
  let swatches = [];

  // --- Color utilities ---

  function hslToRgb(h, s, l) {
    s /= 100;
    l /= 100;
    const k = n => (n + h / 30) % 12;
    const a = s * Math.min(l, 1 - l);
    const f = n => l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)));
    return [Math.round(f(0) * 255), Math.round(f(8) * 255), Math.round(f(4) * 255)];
  }

  function rgbToHex(r, g, b) {
    return '#' + [r, g, b].map(v => v.toString(16).padStart(2, '0')).join('').toUpperCase();
  }

  function hslToHex(h, s, l) {
    const [r, g, b] = hslToRgb(h, s, l);
    return rgbToHex(r, g, b);
  }

  // --- Harmony generation ---

  function randomInt(max) {
    return Math.floor(Math.random() * max);
  }

  const HARMONIES = [
    // Analogous
    function () {
      const base = randomInt(360);
      const step = 25 + randomInt(15);
      return Array.from({ length: NUM_SWATCHES }, (_, i) => {
        const h = (base + i * step) % 360;
        const s = 55 + randomInt(30);
        const l = 35 + randomInt(30);
        return hslToHex(h, s, l);
      });
    },
    // Complementary
    function () {
      const h1 = randomInt(360);
      const h2 = (h1 + 180) % 360;
      const s = 55 + randomInt(30);
      const l = 40 + randomInt(25);
      const colors = [];
      for (let i = 0; i < NUM_SWATCHES; i++) {
        const h = i % 2 === 0 ? h1 : h2;
        const lVar = l + (i - 2) * 8;
        colors.push(hslToHex(h, s, Math.max(25, Math.min(75, lVar))));
      }
      return colors;
    },
    // Triadic
    function () {
      const base = randomInt(360);
      const s = 55 + randomInt(30);
      const l = 45 + randomInt(20);
      return Array.from({ length: NUM_SWATCHES }, (_, i) => {
        const h = (base + i * 120) % 360;
        const lVar = l + (i - 2) * 6;
        return hslToHex(h, s, Math.max(25, Math.min(75, lVar)));
      });
    },
    // Split complementary
    function () {
      const base = randomInt(360);
      const s = 55 + randomInt(30);
      const l = 45 + randomInt(20);
      const hues = [base, (base + 150) % 360, (base + 210) % 360];
      return Array.from({ length: NUM_SWATCHES }, (_, i) => {
        const h = hues[i % 3];
        const lVar = l + (i - 2) * 7;
        return hslToHex(h, s, Math.max(25, Math.min(75, lVar)));
      });
    },
    // Monochromatic
    function () {
      const h = randomInt(360);
      const s = 55 + randomInt(30);
      const baseL = 30 + randomInt(10);
      return Array.from({ length: NUM_SWATCHES }, (_, i) => {
        const l = baseL + i * 10;
        return hslToHex(h, s, Math.min(80, l));
      });
    }
  ];

  function generatePalette() {
    const harmony = HARMONIES[randomInt(HARMONIES.length)];
    return harmony();
  }

  // --- State management ---

  function createSwatchState(hex, locked) {
    return { hex, locked: locked || false };
  }

  function initSwatches() {
    const colors = generatePalette();
    swatches = colors.map(hex => createSwatchState(hex));
    renderSwatches();
  }

  function regenerate() {
    const newColors = generatePalette();
    let newIndex = 0;
    swatches = swatches.map(sw => {
      if (sw.locked) return sw;
      const hex = newColors[newIndex];
      newIndex = (newIndex + 1) % newColors.length;
      return createSwatchState(hex);
    });
    renderSwatches();
  }

  // --- Rendering ---

  function renderSwatches() {
    swatchesContainer.innerHTML = '';
    swatches.forEach((sw, index) => {
      const swatchEl = document.createElement('div');
      swatchEl.className = 'swatch' + (sw.locked ? ' locked' : '');

      const colorArea = document.createElement('div');
      colorArea.className = 'color-area';
      colorArea.style.backgroundColor = sw.hex;

      const hexLabel = document.createElement('span');
      hexLabel.className = 'hex';
      hexLabel.textContent = sw.hex;
      colorArea.appendChild(hexLabel);

      const lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', sw.locked ? 'true' : 'false');
      lockBtn.setAttribute('aria-label',
        (sw.locked ? 'Unlock' : 'Lock') + ' color ' + sw.hex
      );

      const icon = document.createElement('span');
      icon.className = 'lock-icon';
      icon.textContent = sw.locked ? '🔒' : '🔓';
      icon.setAttribute('aria-hidden', 'true');
      lockBtn.appendChild(icon);

      const label = document.createElement('span');
      label.textContent = sw.locked ? 'Locked' : 'Lock';
      lockBtn.appendChild(label);

      lockBtn.addEventListener('click', () => {
        swatches[index].locked = !swatches[index].locked;
        renderSwatches();
      });

      swatchEl.appendChild(colorArea);
      swatchEl.appendChild(lockBtn);
      swatchesContainer.appendChild(swatchEl);
    });
  }

  // --- Init ---

  generateBtn.addEventListener('click', regenerate);
  initSwatches();
})();
